import{_ as n,a8 as a,o as l,c as s,ah as o,K as r}from"./chunks/framework.CC2XyBp0.js";import"./chunks/theme.CrQxOIlk.js";const q=JSON.parse('{"title":"电商智能客服问答系统（RAG）","description":"","frontmatter":{"tags":["档案","RAG","智能客服","向量检索","vLLM"]},"headers":[],"relativePath":"vault/档案/电商智能客服RAG系统-复盘笔记.md","filePath":"vault/档案/电商智能客服RAG系统-复盘笔记.md","lastUpdated":1784036177000}'),i={name:"vault/档案/电商智能客服RAG系统-复盘笔记.md"};function h(p,t,b,c,g,u){const e=a("NolebaseGitContributors"),d=a("NolebaseGitChangelog");return l(),s("div",null,[t[0]||(t[0]=o(`<h1 id="电商智能客服问答系统-rag" tabindex="-1">电商智能客服问答系统（RAG） <a class="header-anchor" href="#电商智能客服问答系统-rag" aria-label="Permalink to “电商智能客服问答系统（RAG）”">​</a></h1><blockquote><p>五层分层架构 RAG 客服系统——BERT 意图分类 + 双路混合检索 + Reranker 精排 + 三级缓存，覆盖八大知识域，端到端 P50 &lt; 2s。</p></blockquote><h2 id="项目概览" tabindex="-1">项目概览 <a class="header-anchor" href="#项目概览" aria-label="Permalink to “项目概览”">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>内容</th></tr></thead><tbody><tr><td><strong>项目周期</strong></td><td>2024.12 - 2025.08</td></tr><tr><td><strong>核心技术</strong></td><td>BERT / BGE-M3 / Milvus / vLLM / Redis / FastAPI</td></tr><tr><td><strong>角色</strong></td><td>主导架构设计、检索优化、缓存方案、部署上线</td></tr><tr><td><strong>核心成果</strong></td><td>意图准确率 95%+ / 缓存命中率 60%+ / 响应延迟降低 70%</td></tr></tbody></table><h2 id="项目背景" tabindex="-1">项目背景 <a class="header-anchor" href="#项目背景" aria-label="Permalink to “项目背景”">​</a></h2><p>公司电商平台客服团队每天处理大量重复咨询（退换货政策、物流时效、尺码推荐等）。分析了近 3 个月的客服咨询日志，退换货、物流、商品参数等高频意图占总咨询量 60% 以上。人工回复存在两大问题：</p><ul><li><strong>标准不一致</strong>：不同客服回答口径不同，用户体验有差异</li><li><strong>高峰期排队</strong>：大促期间咨询量暴增，人工客服响应慢，用户满意度下降</li></ul><h3 id="核心挑战" tabindex="-1">核心挑战 <a class="header-anchor" href="#核心挑战" aria-label="Permalink to “核心挑战”">​</a></h3><ul><li>如何精准识别用户模糊口语化的查询意图</li><li>如何在八大知识域中高效检索相关内容</li><li>如何保证回答准确合规，控制幻觉</li><li>如何在高并发下保持低延迟</li></ul><hr><h2 id="核心架构-五层分层设计" tabindex="-1">核心架构：五层分层设计 <a class="header-anchor" href="#核心架构-五层分层设计" aria-label="Permalink to “核心架构：五层分层设计”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│               第五层：安全审核                │</span></span>
<span class="line"><span>│     内容合规 / 事实校验 / 语气规范           │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│               第四层：LLM 生成                │</span></span>
<span class="line"><span>│   分场景温度控制 / Prompt模板矩阵 / 溯源引用  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│               第三层：Reranker 精排            │</span></span>
<span class="line"><span>│    BGE-Reranker-v2-m3 Cross-Encoder         │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│               第二层：混合检索                 │</span></span>
<span class="line"><span>│    稠密检索（BGE-M3）+ 稀疏检索（BM25）       │</span></span>
<span class="line"><span>│           RRF 融合 + 动态权重调整             │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│               第一层：意图识别                 │</span></span>
<span class="line"><span>│   BERT-wwm-base 微调 / 四级置信度策略          │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span>
<span class="line"><span>              ↗ 三级缓存体系 ↖</span></span>
<span class="line"><span>         L1 精确匹配 / L2 语义匹配 / L3 全链路</span></span></code></pre></div><p>模块化可扩展的五层架构，每一层都可以独立优化和替换。</p><h3 id="第一层-意图识别-bert-微调" tabindex="-1">第一层：意图识别（BERT 微调） <a class="header-anchor" href="#第一层-意图识别-bert-微调" aria-label="Permalink to “第一层：意图识别（BERT 微调）”">​</a></h3><p>BERT-wwm-base 微调做意图分类，覆盖八大核心知识域：退换货、物流、商品参数、比价、活动、教程、尺码、发票支付。</p><h4 id="三阶段渐进训练" tabindex="-1">三阶段渐进训练 <a class="header-anchor" href="#三阶段渐进训练" aria-label="Permalink to “三阶段渐进训练”">​</a></h4><ol><li><strong>通用预训练微调</strong>：在通用中文文本分类数据集上微调，让模型学会基本分类能力</li><li><strong>领域适应微调</strong>：在电商客服领域弱标注数据上继续微调，熟悉电商咨询表述风格</li><li><strong>精标数据微调</strong>：在约 5000 条精标数据上最终微调</li></ol><p>为什么分三阶段而不是直接在精标数据上微调？因为精标数据只有约 5000 条，直接微调容易过拟合。渐进训练让模型先有通用分类能力，再适应领域表述，最后精修到具体类别。</p><h4 id="标注数据来源" tabindex="-1">标注数据来源 <a class="header-anchor" href="#标注数据来源" aria-label="Permalink to “标注数据来源”">​</a></h4><ul><li>客服团队已有粗分类标签约 3000 条 → 清洗标准化</li><li>从原始日志补充标注约 2000 条 → 重点覆盖模糊表述和长尾场景</li><li>每个意图最少 300+ 条样本</li><li>质量控制：随机抽 200 条由客服运营二次审核，一致性 &gt; 90%</li></ul><h4 id="四级置信度策略" tabindex="-1">四级置信度策略 <a class="header-anchor" href="#四级置信度策略" aria-label="Permalink to “四级置信度策略”">​</a></h4><p>BERT 输出的是概率分布，不是所有查询都能高置信归到一个类别。</p><table tabindex="0"><thead><tr><th>级别</th><th>置信度</th><th>处理方式</th></tr></thead><tbody><tr><td>高置信</td><td>&gt; 0.85</td><td>直接路由到对应意图检索流程</td></tr><tr><td>中等</td><td>0.6 ~ 0.85</td><td>路由对应意图 + 附加 Query 扩展</td></tr><tr><td>低置信</td><td>0.3 ~ 0.6</td><td>多意图并行检索，LLM 综合判断</td></tr><tr><td>无关</td><td>&lt; 0.3</td><td>走兜底，礼貌告知并转人工</td></tr></tbody></table><p>只取最高概率的问题：一个用户问&quot;这个衣服能退吗质量怎么样&quot;，BERT 可能给退换货 0.55、商品参数 0.45，硬路由到退换货会丢失&quot;质量&quot;意图。</p><h3 id="第二层-混合检索-双路召回" tabindex="-1">第二层：混合检索（双路召回） <a class="header-anchor" href="#第二层-混合检索-双路召回" aria-label="Permalink to “第二层：混合检索（双路召回）”">​</a></h3><p>BGE-M3 稠密检索 + BM25 稀疏检索双路召回，RRF 融合。</p><h4 id="为什么需要双路" tabindex="-1">为什么需要双路 <a class="header-anchor" href="#为什么需要双路" aria-label="Permalink to “为什么需要双路”">​</a></h4><ul><li><strong>稠密检索（BGE-M3）</strong>：擅长语义理解——&quot;这款手机续航怎么样&quot;→匹配到电池评测内容</li><li><strong>稀疏检索（BM25）</strong>：擅长精确关键词——&quot;7天无理由退货&quot;→精确匹配政策条款</li><li><strong>RRF 融合</strong>：让两种优势互补——语义相关 + 关键词精确的文档双路都靠前</li></ul><h4 id="动态权重调整" tabindex="-1">动态权重调整 <a class="header-anchor" href="#动态权重调整" aria-label="Permalink to “动态权重调整”">​</a></h4><p>根据意图识别结果动态调整稠密/稀疏权重：</p><table tabindex="0"><thead><tr><th>意图类型</th><th>稠密权重</th><th>稀疏权重</th><th>原因</th></tr></thead><tbody><tr><td>退换货政策</td><td>0.4</td><td>0.6</td><td>需要精确关键词匹配政策条款</td></tr><tr><td>商品参数</td><td>0.7</td><td>0.3</td><td>语义理解比关键词更重要</td></tr><tr><td>活动促销</td><td>0.5</td><td>0.5</td><td>关键词 + 语义双重需求</td></tr></tbody></table><h4 id="query-理解优化" tabindex="-1">Query 理解优化 <a class="header-anchor" href="#query-理解优化" aria-label="Permalink to “Query 理解优化”">​</a></h4><p>在检索之前做 Query 理解预处理：</p><ul><li><strong>口语归一化</strong>：200+ 条规则映射表（&quot;买了多久能退&quot;→&quot;退换货时效 条件&quot;）</li><li><strong>关键词扩展</strong>：同义词替换 + 相关词扩展</li><li><strong>子查询分解</strong>：复杂问题拆成多个子查询并行检索</li></ul><p>规则覆盖不了的走 LLM Query 改写，但只在中等/低置信度时触发，避免不必要的 LLM 调用增加延迟。</p><h3 id="第三层-reranker-精排" tabindex="-1">第三层：Reranker 精排 <a class="header-anchor" href="#第三层-reranker-精排" aria-label="Permalink to “第三层：Reranker 精排”">​</a></h3><p>BGE-Reranker-v2-m3 做精排。召回阶段从百万级文档中快速取 Top-50（速度快，精度够用），Rerank 阶段对这 50 条精排（精度高，50 条推理量可控）。</p><p>召回粗排 + Rerank 精排是 RAG 系统的标准两阶段检索架构。</p><h4 id="bge-m3-vs-bge-reranker-的区别" tabindex="-1">BGE-M3 vs BGE-Reranker 的区别 <a class="header-anchor" href="#bge-m3-vs-bge-reranker-的区别" aria-label="Permalink to “BGE-M3 vs BGE-Reranker 的区别”">​</a></h4><table tabindex="0"><thead><tr><th>模型类型</th><th>架构</th><th>速度</th><th>精度</th><th>用途</th></tr></thead><tbody><tr><td>BGE-M3</td><td>双塔模型（Query/Doc 分别编码）</td><td>快</td><td>有限</td><td>粗排召回</td></tr><tr><td>BGE-Reranker</td><td>Cross-Encoder（Query+Doc 交互推理）</td><td>慢</td><td>高</td><td>精排</td></tr></tbody></table><p>Reranker 输出的分数是相对值不是绝对概率——0.87 不代表 87% 相关，只表示比 0.65 分更相关。只能用来排序，不能设绝对阈值。</p><h4 id="效果" tabindex="-1">效果 <a class="header-anchor" href="#效果" aria-label="Permalink to “效果”">​</a></h4><p>Top-1 准确率从单路向量检索的 71% 提升到 82%——因为 Reranker 能捕捉初排无法辨别的细微差异。比如用户问&quot;退货政策&quot;，向量检索可能把&quot;退款流程&quot;排在前面（语义接近但意图不同），Reranker 能识别出二者是不同意图。</p><h3 id="第四层-llm-生成" tabindex="-1">第四层：LLM 生成 <a class="header-anchor" href="#第四层-llm-生成" aria-label="Permalink to “第四层：LLM 生成”">​</a></h3><h4 id="意图-×-场景-二维-prompt-模板矩阵" tabindex="-1">（意图 × 场景）二维 Prompt 模板矩阵 <a class="header-anchor" href="#意图-×-场景-二维-prompt-模板矩阵" aria-label="Permalink to “（意图 × 场景）二维 Prompt 模板矩阵”">​</a></h4><p>不同意图、不同场景用不同 Prompt 模板，不是所有问题一套模板。</p><h4 id="分场景温度控制" tabindex="-1">分场景温度控制 <a class="header-anchor" href="#分场景温度控制" aria-label="Permalink to “分场景温度控制”">​</a></h4><table tabindex="0"><thead><tr><th>场景类型</th><th>temperature</th><th>原因</th></tr></thead><tbody><tr><td>事实类（政策、时效、参数）</td><td>0</td><td>几乎只输出最高概率答案，抑制幻觉</td></tr><tr><td>策略类（比价、尺码推荐）</td><td>0.3</td><td>允许轻微多样性，多个选项推荐</td></tr></tbody></table><p>事实类问题温度&gt;0 会让 LLM 可能&quot;创造性&quot;编造政策条款，这在客服场景是致命的。</p><h4 id="为什么温度为-0-还要用-llm-而不直接返回原文" tabindex="-1">为什么温度为 0 还要用 LLM 而不直接返回原文？ <a class="header-anchor" href="#为什么温度为-0-还要用-llm-而不直接返回原文" aria-label="Permalink to “为什么温度为 0 还要用 LLM 而不直接返回原文？”">​</a></h4><ol><li><strong>信息提取和重组</strong>：原文可能是长篇政策，LLM 提取关键信息整合成一句精准回答</li><li><strong>多文档信息整合</strong>：一个查询涉及多篇文档，LLM 合并成连贯回答</li><li><strong>多轮上下文理解</strong>：连续提问需要结合历史上下文消歧</li></ol><p>温度=0 只是为了抑制创造性，不是否定 LLM 的信息提取、整合和上下文理解能力。</p><h3 id="第五层-安全审核" tabindex="-1">第五层：安全审核 <a class="header-anchor" href="#第五层-安全审核" aria-label="Permalink to “第五层：安全审核”">​</a></h3><p>三段式安全审核：</p><ol><li><strong>内容合规审核</strong>：检查是否涉及虚假宣传、价格欺诈等</li><li><strong>事实校验审核</strong>：关键事实（退货天数、受理条件）是否在参考文档中有原文依据</li><li><strong>语气规范审核</strong>：语气是否专业礼貌，避免生硬或冒犯</li></ol><p>每段审核由规则引擎+轻量模型组合执行，不合格的回答会被拦截或修正后重新生成。</p><h3 id="三级缓存体系" tabindex="-1">三级缓存体系 <a class="header-anchor" href="#三级缓存体系" aria-label="Permalink to “三级缓存体系”">​</a></h3><p>上线运行 2 个月稳定期命中率约 60%。</p><table tabindex="0"><thead><tr><th>级别</th><th>缓存方式</th><th>命中率</th><th>响应速度</th></tr></thead><tbody><tr><td>L1 精确匹配</td><td>Redis 精确匹配键</td><td>~38%</td><td>&lt; 5ms</td></tr><tr><td>L2 语义匹配</td><td>Redis 语义索引最近邻</td><td>~18%</td><td>~30ms</td></tr><tr><td>L3 全链路</td><td>全链路结果缓存</td><td>~6%</td><td>~100ms</td></tr></tbody></table><p>L2 缓存实现：用户 Query 经 BGE-M3 编码后，在 Redis 有序集合中找最近邻。覆盖了 L1 漏掉的表述变体（比如&quot;能退货吗&quot;和&quot;退换货政策&quot;语义相同但字面不同）。</p><h3 id="冷热分层存储" tabindex="-1">冷热分层存储 <a class="header-anchor" href="#冷热分层存储" aria-label="Permalink to “冷热分层存储”">​</a></h3><p>知识库访问频率差异大，不分层成本高。</p><table tabindex="0"><thead><tr><th>层级</th><th>访问频率</th><th>存储</th><th>占比</th><th>覆盖查询量</th></tr></thead><tbody><tr><td>热数据</td><td>近7天高频</td><td>Redis 缓存 + Milvus SSD</td><td>~20%</td><td>~60%</td></tr><tr><td>温数据</td><td>7~30天有访问</td><td>Milvus 向量库</td><td>~60%</td><td>~38%</td></tr><tr><td>冷数据</td><td>30天+无访问</td><td>对象存储归档</td><td>~20%</td><td>~2%</td></tr></tbody></table><p>每天凌晨定时统计各知识条目的近 7 天访问次数，低于阈值降级，被重新启用则升级。</p><hr><h2 id="幻觉控制策略" tabindex="-1">幻觉控制策略 <a class="header-anchor" href="#幻觉控制策略" aria-label="Permalink to “幻觉控制策略”">​</a></h2><p>RAG 系统的幻觉有三个来源，针对性控制：</p><h3 id="来源一-知识库边界外的查询" tabindex="-1">来源一：知识库边界外的查询 <a class="header-anchor" href="#来源一-知识库边界外的查询" aria-label="Permalink to “来源一：知识库边界外的查询”">​</a></h3><p>用户问了知识库里没有覆盖的问题，LLM 拿一堆不相关结果被迫生成，就会编造。</p><p><strong>控制策略</strong>：四级置信度路由的 L4 兜底——置信度&lt;0.3 时不触发 RAG，直接回复&quot;该问题暂无法自动回复，已转接人工客服&quot;。关键原则是宁愿说&quot;不知道&quot;也不能编造。</p><h3 id="来源二-检索噪声" tabindex="-1">来源二：检索噪声 <a class="header-anchor" href="#来源二-检索噪声" aria-label="Permalink to “来源二：检索噪声”">​</a></h3><p>检索结果看起来相关但实质偏离，LLM 基于&quot;半相关&quot;内容生成答案，细节出错。</p><p><strong>控制策略</strong>：双路检索 + Reranker 精排把 Top-1 准确率从 71% 拉到 82%；三段式审核的第二段&quot;事实校验&quot;检查关键数字是否在原文中有依据。</p><h3 id="来源三-生成阶段固有偏差" tabindex="-1">来源三：生成阶段固有偏差 <a class="header-anchor" href="#来源三-生成阶段固有偏差" aria-label="Permalink to “来源三：生成阶段固有偏差”">​</a></h3><p>即使检索完全正确，LLM 可能用预训练知识&quot;脑补&quot;——比如文档说&quot;支持 7 天无理由退货&quot;，LLM 把预训练学的&quot;电商常见规则 15 天&quot;混进去了。</p><p><strong>控制策略</strong>：分场景温度控制（事实类 0）+ 答案末尾附信息来源，让用户知道信息来源，也方便运营溯源。</p><hr><h2 id="核心成果" tabindex="-1">核心成果 <a class="header-anchor" href="#核心成果" aria-label="Permalink to “核心成果”">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>数值</th></tr></thead><tbody><tr><td>意图分类整体准确率</td><td>&gt; 93%</td></tr><tr><td>高频意图准确率</td><td>&gt; 96%</td></tr><tr><td>三级缓存命中率</td><td>~ 60%（上线 2 个月稳定期）</td></tr><tr><td>端到端 P50 延迟</td><td>&lt; 2s（本地部署）</td></tr><tr><td>L1 缓存命中延迟</td><td>~ 5ms</td></tr><tr><td>覆盖知识域</td><td>8 个（退换货/物流/商品参数/比价/活动/教程/尺码/发票支付）</td></tr><tr><td>知识库条目</td><td>1000+ 条（经运营专家审核）</td></tr><tr><td>Top-1 准确率（vs 单路向量）</td><td>71% → 82%</td></tr><tr><td>人工介入率下降</td><td>~ 40%</td></tr></tbody></table><hr><h2 id="关键技术决策" tabindex="-1">关键技术决策 <a class="header-anchor" href="#关键技术决策" aria-label="Permalink to “关键技术决策”">​</a></h2><h3 id="为什么-bert-110m-参数能做到-93-准确率" tabindex="-1">为什么 BERT 110M 参数能做到 &gt;93% 准确率 <a class="header-anchor" href="#为什么-bert-110m-参数能做到-93-准确率" aria-label="Permalink to “为什么 BERT 110M 参数能做到 &gt;93% 准确率”">​</a></h3><p>三个因素叠加让小模型在这个场景足够：</p><ol><li><strong>任务本身不复杂</strong>：八大意图的语义边界清晰，不是需要大模型的细粒度区分</li><li><strong>预训练知识迁移</strong>：BERT-wwm-base 在全词掩码预训练时已经学到了电商词汇的语义表示</li><li><strong>数据质量比模型大小更重要</strong>：5000 条高质量数据 + 110M BERT 效果优于 2000 条数据 + 340M BERT</li></ol><p>换个角度：如果需要区分 50+ 个细粒度意图，或者意图边界非常模糊，110M 可能不够。但在八分类高区分度场景下，它是&quot;够用且轻量&quot;的选择。</p><h3 id="embedding-模型为什么选-bge-m3-而不是-bge-large" tabindex="-1">Embedding 模型为什么选 BGE-M3 而不是 bge-large <a class="header-anchor" href="#embedding-模型为什么选-bge-m3-而不是-bge-large" aria-label="Permalink to “Embedding 模型为什么选 BGE-M3 而不是 bge-large”">​</a></h3><p>客服场景有三个特性是 BGE-M3 能提供的：</p><ul><li><strong>稠密 + 稀疏双向量输出</strong> → 一个模型支撑双路检索</li><li><strong>多语言支持</strong> → 中英混杂输入（比如&quot;iPhone15 售后政策&quot;）</li><li><strong>长文本支持（8192 tokens）</strong> → 政策条款、活动规则等长文档</li></ul><p>bge-large-zh 只有 1024 维稠密向量，用了它还要单独跑 BM25，两个模型串联更重。</p><h3 id="为什么用-milvus-而不是其他向量库" tabindex="-1">为什么用 Milvus 而不是其他向量库 <a class="header-anchor" href="#为什么用-milvus-而不是其他向量库" aria-label="Permalink to “为什么用 Milvus 而不是其他向量库”">​</a></h3><table tabindex="0"><thead><tr><th>选型对比</th><th>差异</th></tr></thead><tbody><tr><td>vs FAISS</td><td>是检索库不是数据库——不支持持久化、分布式、元数据过滤</td></tr><tr><td>vs Qdrant</td><td>更灵活，但 Milvus 社区生态更大、更熟悉索引调优</td></tr><tr><td>vs pgvector</td><td>主库是 MySQL，引入 pgvector 增加运维成本，百万级性能不如 Milvus</td></tr></tbody></table><p>选型原则：Milvus 负责&quot;检索快&quot;，Redis 负责&quot;查得快&quot;，MySQL 负责&quot;记得久&quot;，COS 负责&quot;存得省&quot;。各司其职，不互相越界。</p><hr><h2 id="遇到的挑战与解决方案" tabindex="-1">遇到的挑战与解决方案 <a class="header-anchor" href="#遇到的挑战与解决方案" aria-label="Permalink to “遇到的挑战与解决方案”">​</a></h2><h3 id="挑战一-缓存雪崩" tabindex="-1">挑战一：缓存雪崩 <a class="header-anchor" href="#挑战一-缓存雪崩" aria-label="Permalink to “挑战一：缓存雪崩”">​</a></h3><p><strong>问题</strong>：上线第二周，运营一次性更新退换货政策（约 30 条），触发批量缓存失效。Redis 中大量缓存瞬间过期，QPS 从 50 飙升到 200+，延迟从 300ms 飙到 3s。</p><p><strong>根因</strong>：缓存失效时间集中 + 没有随机过期偏移。</p><p><strong>解决</strong>：</p><ol><li>批量更新时给缓存设置随机过期偏移（TTL=3600±300s），避免集中失效</li><li>加本地内存 Caffeine 缓存做 L0 兜底——请求先查本地，miss 再走全链路</li><li>上线缓存预热机制——知识更新后异步重建高频 Query 缓存</li></ol><h3 id="挑战二-reranker-精度退化" tabindex="-1">挑战二：Reranker 精度退化 <a class="header-anchor" href="#挑战二-reranker-精度退化" aria-label="Permalink to “挑战二：Reranker 精度退化”">​</a></h3><p><strong>问题</strong>：上线一个月后运营反馈&quot;最近推荐退换货政策的准确率下降了&quot;。</p><p><strong>分析</strong>：新增 50+ 条活动促销类知识，语义空间和退换货政策有重叠（都涉及&quot;退款&quot;&quot;退货&quot;关键词），旧阈值无法区分新增边界 case。</p><p><strong>解决</strong>：用新知识的标注数据做 Reranker 微调（约 200 条样本），定向提升区分力。建立 Reranker 月度评估机制——每月用固定 500 条标注 query 做离线评测，追踪各知识域 Recall@5 变化趋势。</p><h3 id="挑战三-长尾意图的-llm-超时" tabindex="-1">挑战三：长尾意图的 LLM 超时 <a class="header-anchor" href="#挑战三-长尾意图的-llm-超时" aria-label="Permalink to “挑战三：长尾意图的 LLM 超时”">​</a></h3><p><strong>问题</strong>：部分用户问超长、超复杂的问题（一口气问 4~5 个不相关问题），BERT 归为&quot;其他/无法识别&quot;进入完整链路。多意图并行检索时，Reranker 候选膨胀到 100+ 条，LLM 处理超长上下文时偶尔超时。</p><p><strong>解决</strong>：</p><ol><li>加输入截断——&gt;200 字先做 LLM 拆分成多个子 query 分别处理</li><li>设置 LLM 调用超时机制（10s 超时走原文返回降级），避免长耗时请求阻塞线程池</li></ol><h3 id="挑战四-长文档分块策略优化" tabindex="-1">挑战四：长文档分块策略优化 <a class="header-anchor" href="#挑战四-长文档分块策略优化" aria-label="Permalink to “挑战四：长文档分块策略优化”">​</a></h3><p><strong>问题</strong>：最初用固定 512 token 切块，发现政策类文档经常在条款边界切断——标题在一个 chunk、内容在另一个 chunk。</p><p><strong>解决</strong>：文档类型感知的差异化分块策略——FAQ 按 QA 对切、政策按标题语义边界切、长商品描述用 768 tokens + 128 overlap。每种类型的 splitter 有各自的 separators 优先级。</p><p>在此基础上加父块上下文扩展——子 chunk 召回后，找到所属父文档位置，前后各拼接 1 个相邻 chunk，保证信息完整性。</p><hr><h2 id="技术选型说明" tabindex="-1">技术选型说明 <a class="header-anchor" href="#技术选型说明" aria-label="Permalink to “技术选型说明”">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>选型</th><th>备选</th><th>选型理由</th></tr></thead><tbody><tr><td>意图分类</td><td>BERT-wwm-base 微调</td><td>直接用 LLM / FastText</td><td>110M 参数足够 + 毫秒级响应</td></tr><tr><td>Embedding</td><td>BGE-M3</td><td>bge-large-zh / M3E</td><td>稠密+稀疏双输出，一次推理双路检索</td></tr><tr><td>Reranker</td><td>BGE-Reranker-v2-m3</td><td>无 Reranker 直接 Top-10</td><td>Top-1 准确率从 71% → 82%</td></tr><tr><td>向量库</td><td>Milvus</td><td>FAISS / Qdrant / pgvector</td><td>生产级 + 熟悉 + 扩展性好</td></tr><tr><td>缓存</td><td>Redis 三级缓存</td><td>本地内存</td><td>多实例部署必须共享缓存</td></tr><tr><td>LLM 部署</td><td>vLLM + Qwen3:14B</td><td>API 调用</td><td>数据隐私要求 + 成本控制</td></tr><tr><td>服务框架</td><td>FastAPI</td><td>Flask</td><td>异步支持 + 高并发 + 自动文档</td></tr><tr><td>部署方式</td><td>Docker + Nginx</td><td>裸机部署</td><td>环境一致性 + 易扩缩容</td></tr></tbody></table><hr><h2 id="项目价值与意义" tabindex="-1">项目价值与意义 <a class="header-anchor" href="#项目价值与意义" aria-label="Permalink to “项目价值与意义”">​</a></h2><p>这个项目是从&quot;模型能力&quot;到&quot;系统能力&quot;的进阶——不再是调用一个模型解决单一问题，而是构建完整的检索增强生成系统，涉及意图识别、检索优化、生成控制、缓存体系、部署运维全链路。</p><p>核心设计理念：<strong>按场景做差异化</strong>——不是所有查询都用同一个流程处理，而是根据意图置信度、类型、频率动态选择最合适的处理路径。高频高效、长尾覆盖、精准控本。</p><p>从业务价值看：客服回答质量直接影响用户体验和退单率，这个环节用自研全链路而不是商业 SaaS，换来了对八大知识域的深度优化能力和完全可控的迭代速度。</p>`,119)),r(e),r(d)])}const L=n(i,[["render",h]]);export{q as __pageData,L as default};
